import{_ as t,c as r,o as a,ae as s}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Tour des fonctionnalités","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/features.md","filePath":"fr/guide/features.md","lastUpdated":1795170900000}'),i={name:"fr/guide/features.md"};function l(n,e,o,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tour-des-fonctionnalites" tabindex="-1">Tour des fonctionnalités <a class="header-anchor" href="#tour-des-fonctionnalites" aria-label="Permalink to &quot;Tour des fonctionnalités&quot;">​</a></h1><p>Un aperçu rapide de ce que vous utilisez le plus.</p><h2 id="navigation-quotidienne" tabindex="-1">Navigation quotidienne <a class="header-anchor" href="#navigation-quotidienne" aria-label="Permalink to &quot;Navigation quotidienne&quot;">​</a></h2><ul><li>Plusieurs onglets et fenêtres : détacher, regrouper, replier, couper le son, prévisualiser.</li><li>La barre d&#39;adresse propose d&#39;abord les sites connus, puis lance une recherche.</li><li>Palette de commandes (⌘K), recherche d&#39;onglets (⌘⇧A), recherche dans la page (⌘F) et liste des raccourcis dans le menu engrenage.</li></ul><h2 id="confort-visuel" tabindex="-1">Confort visuel <a class="header-anchor" href="#confort-visuel" aria-label="Permalink to &quot;Confort visuel&quot;">​</a></h2><ul><li>Thème : suivre le système, clair ou sombre. Forcer les pages sombres et changer de thème chaque jour est possible.</li><li>Six couleurs d&#39;accent : bleu, violet, sarcelle, vert, orange et rose.</li><li>Barre de favoris : toujours masquée, toujours visible ou uniquement dans le nouvel onglet.</li></ul><h2 id="publicites-et-scripts" tabindex="-1">Publicités et scripts <a class="header-anchor" href="#publicites-et-scripts" aria-label="Permalink to &quot;Publicités et scripts&quot;">​</a></h2><ul><li>Le bloqueur gère abonnements, règles personnelles et liste blanche. Si une mise à jour échoue, les anciennes règles restent actives.</li><li>Les scripts utilisateur (<code>.user.js</code>) se gèrent dans les réglages et s&#39;installent dès la fin du téléchargement.</li></ul><h2 id="videos-et-fichiers" tabindex="-1">Vidéos et fichiers <a class="header-anchor" href="#videos-et-fichiers" aria-label="Permalink to &quot;Vidéos et fichiers&quot;">​</a></h2><ul><li>Les téléchargements peuvent être mis en pause, repris, annulés et relancés. Ensuite, affichez le fichier dans le Finder ou ouvrez-le avec l&#39;app associée.</li><li>Le panneau médias reconnaît les vidéos d&#39;une page et réunit les fragments en un seul MP4.</li></ul><h2 id="raccourcis" tabindex="-1">Raccourcis <a class="header-anchor" href="#raccourcis" aria-label="Permalink to &quot;Raccourcis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td>⌘T / ⌘W</td><td>Nouvel onglet / fermer</td></tr><tr><td>⌘L</td><td>Aller à la barre d&#39;adresse</td></tr><tr><td>⌘F</td><td>Rechercher dans la page</td></tr><tr><td>⌘⇧N</td><td>Fenêtre privée</td></tr><tr><td>⌘K</td><td>Palette de commandes</td></tr><tr><td>⌘⇧A</td><td>Rechercher un onglet</td></tr><tr><td>⌘⇧R</td><td>Mode lecture</td></tr></tbody></table>',12)])])}const f=t(i,[["render",l]]);export{p as __pageData,f as default};
